import re
def expand_ranges(spec):
    out=[]
    s=spec.strip()
    if not s: return []
    for tok in s.split(','):
        t=tok.strip()
        neg=False
        if t.startswith('^'):
            neg=True; t=t[1:].strip()
        if not t: raise ValueError('empty token')
        step=1
        if '/' in t:
            t,k=t.split('/',1)
            t=t.strip(); k=k.strip()
            if not re.fullmatch(r'[-+]?\\d+',k): raise ValueError('bad step')
            step=int(k)
            if step<=0: raise ValueError('bad step')
        m=re.fullmatch(r'\\s*([-+]?\\d+)\\s*-\\s*([-+]?\\d+)\\s*',t)
        if m:
            a,b=int(m.group(1)),int(m.group(2))
            rng=list(range(a,b+1)) if a<=b else list(range(a,b-1,-1))
            vals=rng[::step]
        elif re.fullmatch(r'\\s*([-+]?\\d+)\\s*',t):
            vals=[int(t)]
        else:
            raise ValueError('bad token')
        if neg:
            out=[v for v in out if v not in vals]
        else:
            for v in vals:
                if v not in out: out.append(v)
    return out
