  "content": """"Compare a small set of pre-declared aggregation rules on development data."""
import json
import sys
from collections import defaultdict

import numpy as np

sys.path.insert(0, "/workspace/work")
sys.path.insert(0, "/workspace/suite")
sys.path.insert(0, "/workspace")
import bench  # noqa: E402
from analyze import evaluate, pearson, spearman, M, TARGETS, DOMAINS  # noqa: E402

ITEMS = {i["id"]: i for i in bench.build_all()}


def load(path):
    return json.load(open(path))


def rules(common_ids):
    """Return {name: {item_id: weight}} over `common_ids` only."""
    dom_items = defaultdict(list)
    fam_items = defaultdict(list)
    src_of = {"code_impl": "exec", "code_sci": "exec", "code_qa": "qa", "code_tests": "tests",
              "cowork_if": "if", "cowork_deliv": "deliv",
              "hle_em": "hle", "hle_mc": "hle", "arxivmath": "arxiv", "synth_reason": "synth"}
    for i in common_ids:
        it = ITEMS[i]
        dom_items[it["domain"]].append(i)
        fam_items[(it["domain"], it["family"])].append(i)
    src_items = defaultdict(list)
    for i in common_ids:
        it = ITEMS[i]
        src_items[(it["domain"], src_of[it["family"]])].append(i)

    out = {}
    out["uniform"] = {d: {i: 1.0 for i in ids} for d, ids in dom_items.items()}
    fb = defaultdict(dict)
    fams_per_dom = defaultdict(set)
    for (d, f) in fam_items:
        fams_per_dom[d].add(f)
    for (d, f), ids in fam_items.items():
        for i in ids:
            fb[d][i] = 1.0 / (len(fams_per_dom[d]) * len(ids))
    out["family_balanced"] = dict(fb)
    sb = defaultdict(dict)
    srcs_per_dom = defaultdict(set)
    for (d, s) in src_items:
        srcs_per_dom[d].add(s)
    for (d, s), ids in src_items.items():
        for i in ids:
            sb[d][i] = 1.0 / (len(srcs_per_dom[d]) * len(ids))
    out["source_balanced"] = dict(sb)
    return out


def measured(scores, weightmap):
    out = {}
    for d, w in weightmap.items():
        out[d] = {}
        for m, sc in scores.items():
            vals = [(sc[i], w[i]) for i in w if sc.get(i) is not None]
            out[d][m] = float(np.average([v for v, _ in vals], weights=[x for _, x in vals])) \
                if vals else float("nan")
    return out


def main(scores):
    common = sorted(set.intersection(*[{k for k, v in s.items() if v is not None}
                                       for s in scores.values()]))
    print("common completed items:", len(common))
    best = None
    for name, wm in rules(common).items():
        print("\n===", name)
        meas = measured(scores, wm)
        macro, doms = evaluate(meas, verbose=True)
        if best is None or macro > best[0]:
            best = (macro, name)
    print("\nBEST:", best)
    return best
